{
  "id": "V068",
  "checks": [
    {
      "field": "purpose",
      "score": 2,
      "reason": "국내 기업 소식을 영어 독자에게 전달하려는 목적이 보존되었습니다."
    },
    {
      "field": "action",
      "score": 2,
      "reason": "한국어 기사를 영어로 번역하고 편집자가 원문과 비교해 검토합니다."
    },
    {
      "field": "object",
      "score": 2,
      "reason": "기업 소식 기사와 한국어 기사 내용이 명시되어 있습니다."
    },
    {
      "field": "input",
      "score": 2,
      "reason": "한국어 기사 내용이 입력으로 보존되었습니다."
    },
    {
      "field": "output",
      "score": 2,
      "reason": "영어 독자가 이해할 수 있는 번역문이 보존되었습니다."
    },
    {
      "field": "constraints",
      "score": 2,
      "reason": "고유명사·수치 누락 확인과 원문에 없는 인용·성과 미추가 조건이 보존되었습니다."
    },
    {
      "field": "no_added_functions",
      "score": 2,
      "reason": "뷰에서 원문에 없는 기능을 추가했다고 볼 근거가 없습니다."
    },
    {
      "field": "roles",
      "score": 2,
      "reason": "해외 배포 담당자, 편집자, 번역 기능의 역할이 구분되고 게시 결정은 편집자에게 남아 있습니다."
    }
  ],
  "issues": [],
  "permission_interpretation": "게시 여부 결정은 편집자에게 있습니다. 뷰는 AI가 게시하거나 승인한다고 주장하지 않습니다."
}
